14	/// <see cref="TextInputChanged"/> when the value actually changed.
15	///
16	/// The keyboard is diffed once per frame in <see cref="PreUpdate"/> (edge-triggered
17	/// against the previous state) so every focused field shares one diff. Which field
18	/// is focused is decided by game code — this system only reads the flag (see the
19	/// "focus is game-owned" premise).
20	[With(typeof(TextInputComponent))]
21	public class TextInputSystem : AEntitySetSystem<GameState>
22	{
23	    private KeyboardState _previous;
24	    private readonly List<char> _typed = new();
25	    private bool _backspace;
26	
27	    public TextInputSystem(World world) : base(world)
28	    {
29	        _previous = Keyboard.GetState();
30	    }
31	
32	    protected override void PreUpdate(GameState state)
33	    {
34	        _typed.Clear();
35	        _backspace = false;
36	
37	        var current = Keyboard.GetState();
38	        foreach (var key in current.GetPressedKeys())
39	        {
40	            if (_previous.IsKeyDown(key)) continue; // only keys newly pressed this frame
41	            if (key == Keys.Back) { _backspace = true; continue; }
42	            var c = KeyToChar(key);
43	            if (c != '\0') _typed.Add(c);
44	        }
45	
46	        _previous = current;
47	    }
48	
49	    protected override void Update(GameState state, in Entity entity)
50	    {
51	        ref var input = ref entity.Get<TextInputComponent>();
52	        if (!input.Focused) return;
53	        if (!_backspace && _typed.Count == 0) return;
54	
55	        var text = input.Text ?? string.Empty;
56	        var original = text;
57	
58	        if (_backspace && text.Length > 0)
59	            text = text[..^1];
60	
61	        foreach (var c in _typed)
62	        {
63	            if (input.MaxLength > 0 && text.Length >= input.MaxLength) break;
64	            if (!Accepts(input.Mask, c)) continue;
65	            text += c;
66	        }
67	
68	        if (text == original) return;
69	
70	        input.Text = text;
71	        if (input.TextEntity.IsAlive && input.TextEntity.Has<DynamicTextComponent>())
72	        {
73	            ref var display = ref input.TextEntity.Get<DynamicTextComponent>();
74	            display.TextContent = text;
75	        }
76	
77	        World.Publish(new TextInputChanged(entity, text));
78	    }
79	
80	    private static bool Accepts(TextInputMask mask, char c) => mask switch
81	    {
82	        TextInputMask.Numeric => c is >= '0' and <= '9',
83	        _ => true,
84	    };
85	
86	    /// Maps a key to a printable character (lowercase, no shift handling — this is a
87	    /// minimal field). Returns '\0' for keys that produce no character; the mask
88	    /// does the final filtering.
89	    private static char KeyToChar(Keys key) => key switch
90	    {
91	        >= Keys.D0 and <= Keys.D9 => (char)('0' + (key - Keys.D0)),
92	        >= Keys.NumPad0 and <= Keys.NumPad9 => (char)('0' + (key - Keys.NumPad0)),
93	        >= Keys.A and <= Keys.Z => (char)('a' + (key - Keys.A)),
94	        Keys.Space => ' ',
95	        _ => '\0',
96	    };
97	}
