30	namespace MonoDreams.Demo.Physics;
31	
32	/// Physics module demo. 10 balls launch in random directions and bounce inside a
33	/// closed boundary under gravity. The floor adds extra upward speed on contact so
34	/// balls keep oscillating (the demo is self-sustaining, not damped). Solid red balls
35	/// collide with walls AND each other; hollow (outline-only) blue balls only collide
36	/// with walls (layer-isolated from reds; blue↔blue is filtered in the bounce system).
37	///
38	/// Visual feedback (FlashComponent + FlashSystem): a wall hit blinks the ball's own
39	/// vivid tint; two balls colliding pop a brighter flash on BOTH balls regardless of
40	/// speed. The floor is a thick line — cream when the boost is off, green when on —
41	/// and blinks bright green when a ball lands on it while the boost is on.
42	public class PhysicsDemoScreen : IGameScreen
43	{
44	    private const float BoundaryHalfWidth  = 380f;
45	    private const float BoundaryHalfHeight = 220f;
46	    private const float WallThickness      = 20f;
47	
48	    private const float Gravity      = 1200f;    // px/s²
49	    private const float Restitution  = 0.92f;    // wall/ball bounce energy retention
50	    private const float FloorBoost   = 260f;     // extra upward px/s on floor contact
51	    private const float MaxFallSpeed = 1400f;    // safety cap to prevent tunneling
52	
53	    private const float FloorVisualThickness = 6f;     // thick floor line vs the 2px boundary
54	    private const float FlashDuration        = 0.25f;  // seconds for a blink to fade back
55	
56	    private const float MinSpawnSpeed = 120f;    // random initial-velocity speed range
57	    private const float MaxSpawnSpeed = 220f;
58	    private const float MinBallRadius = 5f;      // random per-ball size range
59	    private const float MaxBallRadius = 10f;
60	    private const float BlueBallBorder = 2f;     // outline thickness for the hollow blue balls
61	    // Collider and rendered circle share this polygon resolution so the contact
62	    // shape is exactly the drawn silhouette (see CreateBall). Tangency no longer
63	    // depends on it — only roundness-of-look and narrowphase cost do — so it can be
64	    // lowered for cheaper narrowphase at very high ball counts.
65	    private const int BallSegments = 32;
66	    // Speed clamp keeps the self-sustaining floor-boost loop from compounding into
67	    // tunnelling speeds. Sits just above a full-height free-fall (~1030 px/s) so
68	    // normal bounces are untouched but runaway energy is capped.
69	    private const float MaxBallSpeed  = 1050f;
70	
71	    private const int DefaultRedCount  = 7;
72	    private const int DefaultBlueCount = 3;
73	    private const int MaxBallsPerColor = 999999; // clamp on the editable counts
74	
75	    /// Floor line tints: regular (boost off), green (boost on), bright blink on a boosted hit.
76	    private static readonly Color FloorRegularColor = SproutPalette.TextLight;
77	    private static readonly Color FloorActiveColor  = new(106, 190, 89);
78	    private static readonly Color FloorFlashColor   = new(190, 255, 150);
79	
80	    private const int RedBallLayer  = 0;
81	    private const int BlueBallLayer = 1;
82	    // Walls own both layers so red and blue both collide with them.
83	
84	    private readonly ContentManager _content;
85	    private readonly GraphicsDevice _graphicsDevice;
86	    private readonly MonoDreams.Component.Camera _camera;
87	    private readonly ViewportManager _viewportManager;
88	    private readonly SpriteBatch _spriteBatch;
89	    private readonly IParallelRunner _runner;
90	    private readonly World _world;
91	    private readonly Dictionary<RenderTargetID, RenderTarget2D> _renderTargets;
92	    private readonly BitmapFont _font;
93	
94	    private ScreenController? _screenController;
95	    private readonly List<Entity> _balls = new();
96	    private readonly Random _rng = new();
97	    private Entity _gravityToggle;
98	    private Entity _floorBoostToggle;
99	    private Entity _floorVisual;
100	    private Entity _redInput;
101	    private Entity _blueInput;
102	    private int _redCount = DefaultRedCount;
103	    private int _blueCount = DefaultBlueCount;
104	    private bool _gravityOn = true;
105	    private bool _floorBoostOn = true;
106	    private bool _paused;
107	
108	    public ISystem<GameState> UpdateSystem { get; }
109	    public ISystem<GameState> DrawSystem { get; }
110	    public World World => _world;
111	
112	    public PhysicsDemoScreen(GraphicsDevice graphicsDevice, ContentManager content,
113	        MonoDreams.Component.Camera camera, ViewportManager viewportManager, SpriteBatch spriteBatch,
114	        IParallelRunner runner)
115	    {
116	        _graphicsDevice = graphicsDevice;
117	        _content = content;
118	        _camera = camera;
119	        _viewportManager = viewportManager;
120	        _spriteBatch = spriteBatch;
121	        _runner = runner;
122	        _renderTargets = new Dictionary<RenderTargetID, RenderTarget2D>
123	        {
124	            { RenderTargetID.Main, new RenderTarget2D(graphicsDevice, viewportManager.VirtualWidth, viewportManager.VirtualHeight) },
125	            { RenderTargetID.UI,   new RenderTarget2D(graphicsDevice, viewportManager.VirtualWidth, viewportManager.VirtualHeight) },
126	            { RenderTargetID.HUD,  new RenderTarget2D(graphicsDevice, viewportManager.VirtualWidth, viewportManager.VirtualHeight) },
127	        };
128	        _font = content.Load<BitmapFont>("Fonts/UAV-OSD-Sans-Mono-72-White-fnt");
129	
130	        camera.Position = Vector2.Zero;
131	
132	        _world = new World();
133	        UpdateSystem = CreateUpdateSystem();
134	        DrawSystem = CreateDrawSystem();
135	    }
136	
137	    public void Load(ScreenController screenController, ContentManager content)
138	    {
139	        _screenController = screenController;
140	        _world.Subscribe<DemoButtonClicked>(OnButtonClicked);
141	        _world.Subscribe<TextInputChanged>(OnTextInputChanged);
142	
143	        var cursorTextures = new Dictionary<CursorType, Texture2D>
144	        {
145	            [CursorType.Default] = content.Load<Texture2D>("Cursor/default"),
146	            [CursorType.Pointer] = content.Load<Texture2D>("Cursor/pointer"),
147	            [CursorType.Hand]    = content.Load<Texture2D>("Cursor/hand"),
148	        };
149	        MonoDreams.Cursor.Cursor.Create(_world, cursorTextures, RenderTargetID.HUD);
150	
151	        CreateBoundary();
152	        CreateFloorVisual();
153	        CreateWalls();
154	        RebuildBalls();
155	        BuildHud(content);
156	    }
157	
158	    // ─── public bridges for the keyboard system ───────────────────────────────
159	
160	    public void GoBackToLauncher() => _screenController?.LoadScreen(DemoScreens.Launcher);
161	
162	    public void TogglePause() => _paused = !_paused;
163	
164	    public void ToggleGravity()
165	    {
166	        if (!_gravityToggle.IsAlive || !_gravityToggle.Has<ToggleSwitchComponent>()) return;
167	        var sw = _gravityToggle.Get<ToggleSwitchComponent>();
168	        sw.On = !sw.On;
169	        _gravityOn = sw.On;
170	        _gravityToggle.Set(sw);
171	        WakeAllBalls();
172	    }
173	
174	    public void ToggleFloorBoost()
175	    {
176	        if (!_floorBoostToggle.IsAlive || !_floorBoostToggle.Has<ToggleSwitchComponent>()) return;
177	        var sw = _floorBoostToggle.Get<ToggleSwitchComponent>();
178	        sw.On = !sw.On;
179	        _floorBoostOn = sw.On;
180	        _floorBoostToggle.Set(sw);
181	        UpdateFloorBaseColor();
182	        WakeAllBalls();
183	    }
184	
185	    /// Floor line is green while the boost is on, regular cream while it's off.
186	    /// The FlashSystem repaints it to this base color whenever it's not blinking.
187	    private void UpdateFloorBaseColor()
188	    {
189	        if (!_floorVisual.IsAlive || !_floorVisual.Has<FlashComponent>()) return;
190	        ref var flash = ref _floorVisual.Get<FlashComponent>();
191	        flash.BaseColor = _floorBoostOn ? FloorActiveColor : FloorRegularColor;
192	    }
193	
194	    /// Reset spawns a fresh random layout honoring the current red/blue counts.
195	    public void Reset() => RebuildBalls();
196	
197	    /// Wakes every ball (clears the asleep/still state from <see cref="BallRestSystem"/>)
198	    /// so a fresh disturbance — flipping gravity or floor boost — re-energises a settled
199	    /// pile instead of leaving it frozen in place.
200	    public void WakeAllBalls()
201	    {
202	        foreach (var ball in _balls)
203	        {
204	            if (!ball.IsAlive || !ball.Has<BallTagComponent>()) continue;
205	            ref var tag = ref ball.Get<BallTagComponent>();
206	            tag.Asleep = false;
207	            tag.StillTime = 0f;
208	        }
209	    }
210	
211	    public bool GravityEnabled => _gravityOn && !_paused;
212	    public bool VelocityEnabled => !_paused;
213	    public bool FloorBoostEnabled => _floorBoostOn;
214	
215	    /// The thick floor line entity, blinked by the bounce system on a boosted hit.
216	    public Entity FloorVisual => _floorVisual;
217	
218	    /// A random launch velocity: random direction, random speed in the spawn range.
219	    private Vector2 RandomVelocity()
220	    {
221	        var angle = (float)(_rng.NextDouble() * Math.PI * 2.0);
222	        var speed = MinSpawnSpeed + (float)_rng.NextDouble() * (MaxSpawnSpeed - MinSpawnSpeed);
223	        return new Vector2(MathF.Cos(angle) * speed, MathF.Sin(angle) * speed);
224	    }
225	
226	    // ─── button click routing ────────────────────────────────────────────────
227	
228	    private const string RedInputId  = "input.red";
229	    private const string BlueInputId = "input.blue";
230	
231	    private void OnButtonClicked(in DemoButtonClicked msg)
232	    {
233	        // Clicking a number box focuses it (exclusively); clicking anything else
234	        // blurs both so keyboard shortcuts resume.
235	        switch (msg.Id)
236	        {
237	            case RedInputId:  FocusInput(_redInput);  return;
238	            case BlueInputId: FocusInput(_blueInput); return;
239	        }
240	
241	        BlurInputs();
242	        switch (msg.Id)
243	        {
244	            case DemoHeader.BackId: _screenController?.LoadScreen(DemoScreens.Launcher); break;
245	            case DemoHeader.ExitId: _screenController?.Game.Exit(); break;
246	            case "physics.reset":      Reset(); break;
247	            case "physics.pause":      TogglePause(); break;
248	            case "toggle.gravity":     ToggleGravity(); break;
249	            case "toggle.floor-boost": ToggleFloorBoost(); break;
250	        }
251	    }
252	
253	    private void OnTextInputChanged(in TextInputChanged msg)
254	    {
255	        if (msg.Input == _redInput)
256	        {
257	            var n = ParseCount(msg.Text);
258	            if (n == _redCount) return;
259	            _redCount = n;
260	        }
261	        else if (msg.Input == _blueInput)
262	        {
263	            var n = ParseCount(msg.Text);
264	            if (n == _blueCount) return;
265	            _blueCount = n;
266	        }
267	        else return;
268	
269	        RebuildBalls();
270	    }
271	
272	    private static int ParseCount(string text) =>
273	        int.TryParse(text, out var v) ? Math.Clamp(v, 0, MaxBallsPerColor) : 0;
274	
275	    // ─── focus (game-owned; TextInputSystem only reads the flag) ───────────────
276	
277	    private void FocusInput(Entity target)
278	    {
279	        SetFocus(_redInput,  target == _redInput);
280	        SetFocus(_blueInput, target == _blueInput);
281	    }
282	
283	    private void BlurInputs()
284	    {
285	        SetFocus(_redInput,  false);
286	        SetFocus(_blueInput, false);
287	    }
288	
289	    /// Mirrors focus onto both the input's key-capture flag and its button accent
290	    /// (IsActive drives the focused border/text color via DemoButtonInteractionSystem).
291	    private static void SetFocus(Entity input, bool focused)
292	    {
293	        if (!input.IsAlive) return;
294	        if (input.Has<TextInputComponent>())
295	        {
296	            ref var ti = ref input.Get<TextInputComponent>();
297	            ti.Focused = focused;
298	        }
299	        if (input.Has<DemoButtonComponent>())
300	        {
301	            ref var db = ref input.Get<DemoButtonComponent>();
302	            db.IsActive = focused;
303	        }
304	    }
305	
306	    // ─── world entities ──────────────────────────────────────────────────────
307	
308	    private void CreateBoundary()
309	    {
310	        var bounds = new Rectangle(
311	            -(int)BoundaryHalfWidth, -(int)BoundaryHalfHeight,
312	            (int)BoundaryHalfWidth * 2, (int)BoundaryHalfHeight * 2);
313	
314	        var boundary = _world.CreateEntity();
315	        boundary.Set(new TransformComponent(Vector2.Zero));
316	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.2f };
317	        draw.SetMeshData(new RectangleOutlineMeshGenerator(bounds, thickness: 2f, color: SproutPalette.TextLight));
318	        boundary.Set(draw);
319	        boundary.Set<VisibleComponent>();
320	    }
321	
322	    /// Thick horizontal line drawn over the boundary's bottom edge — the floor's
323	    /// visual. Regular cream when the boost is off, green when on, and it blinks
324	    /// bright (via FlashSystem) when a ball lands on it while the boost is on.
325	    /// Sits at LayerDepth 0.25 — above the boundary outline (0.2), below the balls.
326	    private void CreateFloorVisual()
327	    {
328	        var left  = new Vector2(-BoundaryHalfWidth, BoundaryHalfHeight);
329	        var right = new Vector2( BoundaryHalfWidth, BoundaryHalfHeight);
330	        var baseColor = _floorBoostOn ? FloorActiveColor : FloorRegularColor;
331	
332	        var floor = _world.CreateEntity();
333	        floor.Set(new TransformComponent(Vector2.Zero));
334	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.25f };
335	        draw.SetMeshData(new LineMeshGenerator(left, right, FloorVisualThickness, baseColor));
336	        floor.Set(draw);
337	        floor.Set(new FlashComponent(baseColor, FloorFlashColor, FlashDuration));
338	        floor.Set<VisibleComponent>();
339	        _floorVisual = floor;
340	    }
341	
342	    /// Four BoxColliders forming a closed box just outside the visible boundary.
343	    /// Walls share both red and blue layers so both ball categories collide with
344	    /// them. Walls have zero TransformComponent.Delta so even though they're
345	    /// active colliders, the swept test self-skips when they iterate as entity A.
346	    private void CreateWalls()
347	    {
348	        var redAndBlue = new HashSet<int> { RedBallLayer, BlueBallLayer };
349	
350	        // Floor — tagged so the bounce system can apply the extra upward kick.
351	        var floor = CreateWall(new Rectangle(
352	            -(int)(BoundaryHalfWidth + WallThickness),
353	            (int)BoundaryHalfHeight,
354	            (int)((BoundaryHalfWidth + WallThickness) * 2),
355	            (int)WallThickness), redAndBlue);
356	        floor.Set<FloorTag>();
357	
358	        // Ceiling
359	        CreateWall(new Rectangle(
360	            -(int)(BoundaryHalfWidth + WallThickness),
361	            -(int)(BoundaryHalfHeight + WallThickness),
362	            (int)((BoundaryHalfWidth + WallThickness) * 2),
363	            (int)WallThickness), redAndBlue);
364	
365	        // Left wall
366	        CreateWall(new Rectangle(
367	            -(int)(BoundaryHalfWidth + WallThickness),
368	            -(int)BoundaryHalfHeight,
369	            (int)WallThickness,
370	            (int)BoundaryHalfHeight * 2), redAndBlue);
371	
372	        // Right wall
373	        CreateWall(new Rectangle(
374	            (int)BoundaryHalfWidth,
375	            -(int)BoundaryHalfHeight,
376	            (int)WallThickness,
377	            (int)BoundaryHalfHeight * 2), redAndBlue);
378	    }
379	
