388	    /// Despawns the current balls and spawns a fresh random set matching the
389	    /// current red/blue counts. Called on load, on reset, and whenever a count
390	    /// input changes.
391	    private void RebuildBalls()
392	    {
393	        foreach (var ball in _balls)
394	            if (ball.IsAlive) ball.Dispose();
395	        _balls.Clear();
396	
397	        for (var i = 0; i < _redCount; i++)  _balls.Add(CreateBall(BallType.Red));
398	        for (var i = 0; i < _blueCount; i++) _balls.Add(CreateBall(BallType.Blue));
399	    }
400	
401	    private Entity CreateBall(BallType type)
402	    {
403	        var radius = MinBallRadius + (float)_rng.NextDouble() * (MaxBallRadius - MinBallRadius);
404	        var spawn = RandomSpawn(radius);
405	
406	        var entity = _world.CreateEntity();
407	        entity.Set(new TransformComponent(spawn));
408	        entity.Set(new VelocityComponent(RandomVelocity()));
409	        entity.Set(new RigidBodyComponent(mass: 1f));
410	        entity.Set(new BallTagComponent { Type = type });
411	
412	        // Convex collider with BallSegments sides, built from the same radius and
413	        // angles as the rendered circle below, so the collider polygon coincides
414	        // with the drawn silhouette. That makes resting balls sit visually tangent:
415	        // an inscribed octagon would sit inside the rounder render, letting the
416	        // circles overlap even at perfect collider contact. SAT handles the
417	        // polygon-polygon bounce natively.
418	        var layer = type == BallType.Red ? RedBallLayer : BlueBallLayer;
419	        entity.Set(new ConvexColliderComponent(
420	            CircleVertices(radius, segments: BallSegments),
421	            activeLayers: new HashSet<int> { layer }));
422	
423	        // Resting tint + the vivid color the ball blinks to on a wall hit (FlashSystem).
424	        var (color, flashColor) = BallColors(type);
425	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.95f };
426	        // Red balls are solid; blue balls are hollow — just their painted border.
427	        // BallSegments matches the collider so the contact shape is the drawn shape.
428	        IMeshGenerator mesh = type == BallType.Blue
429	            ? new CircleOutlineMeshGenerator(Vector2.Zero, radius, BlueBallBorder, color, segments: BallSegments)
430	            : new CircleMeshGenerator(Vector2.Zero, radius, color, segments: BallSegments);
431	        draw.SetMeshData(mesh);
432	        entity.Set(draw);
433	        entity.Set(new FlashComponent(color, flashColor, FlashDuration));
434	        entity.Set<VisibleComponent>();
435	        return entity;
436	    }
437	
438	    /// A ball type's (resting tint, wall-hit flash tint). Single source of truth so
439	    /// the spawn code and the bounce system agree on a ball's colors.
440	    public static (Color Resting, Color Flash) BallColors(BallType type) => type == BallType.Red
441	        ? (SproutPalette.Crimson, new Color(255, 90, 80))
442	        : (SproutPalette.SkyBlue, new Color(150, 230, 255));
443	
444	    /// A random spawn point inside the boundary, kept a ball-radius clear of the walls.
445	    private Vector2 RandomSpawn(float radius)
446	    {
447	        var margin = radius + 8f;
448	        var x = MathHelper.Lerp(-BoundaryHalfWidth + margin,  BoundaryHalfWidth - margin,  (float)_rng.NextDouble());
449	        var y = MathHelper.Lerp(-BoundaryHalfHeight + margin, BoundaryHalfHeight - margin, (float)_rng.NextDouble());
450	        return new Vector2(x, y);
451	    }
452	
453	    private static Vector2[] CircleVertices(float radius, int segments)
454	    {
455	        var verts = new Vector2[segments];
456	        for (var i = 0; i < segments; i++)
457	        {
458	            var a = MathF.PI * 2f * i / segments;
459	            verts[i] = new Vector2(MathF.Cos(a) * radius, MathF.Sin(a) * radius);
460	        }
461	        return verts;
462	    }
