597	    /// Adapter to the `CreateCollisionMessageDelegate<CollisionMessage>` shape that
598	    /// `TransformCollisionDetectionSystem` expects. Always emits Physics-type messages.
599	    private static CollisionMessage CreateCollisionMessage(
600	        Entity entity, Entity target,
601	        Vector2 contactPoint, Vector2 contactNormal,
602	        float contactTime, float penetrationDepth, int layer)
603	        => new(entity, target, contactPoint, contactNormal, contactTime, penetrationDepth, layer, CollisionType.Physics);
604	
605	    private SequentialSystem<GameState> CreateUpdateSystem()
606	    {
607	        // Reference physics pipeline order (per docs/CORE_TENETS.md §5):
608	        //   Movement → Velocity → Detection → Resolution → Commit
609	        // Movement here is gravity-only; ball↔ball/ball↔wall bouncing is the
610	        // custom resolution stage that subscribes to CollisionMessage.
611	        return new SequentialSystem<GameState>(
612	            new CursorInputSystem(_world),
613	            new IntrinsicSizingSystem(_world),
614	            new AutoLayoutSystem(_world, _viewportManager),
615	            new DemoButtonInteractionSystem(_world),
616	            new TextInputSystem(_world),
617	            new DemoIconRecolorSystem(_world),
618	            new ToggleSwitchSystem(_world),
619	            new PhysicsDemoInputSystem(this),
620	            new GatedGravitySystem(_world, _runner, this),
621	            new BallRestSystem(_world, this),
622	            new GatedVelocitySystem(_world, _runner, this),
623	            new TransformCollisionDetectionSystem<CollisionMessage>(_world, CreateCollisionMessage),
624	            new BallBounceSystem(_world, this),
625	            new BallSpeedClampSystem(_world, MaxBallSpeed),
626	            new FlashSystem(_world),
627	            new TransformCommitSystem(_world, _runner),
628	            new HierarchySystem(_world),
629	            new CursorPositionSystem(_world, _camera, _viewportManager),
630	            new CursorDrawPrepSystem(_world));
631	    }
