791	// ─── bounce resolution ────────────────────────────────────────────────────
792	
793	/// Custom resolution: subscribes to <see cref="CollisionMessage"/>, softly pushes
794	/// the base entity out of penetration (slop + partial correction), then applies a
795	/// relative-velocity impulse along the contact normal — so a ball struck while at
796	/// rest takes on the incoming ball's momentum instead of acting like a wall. A fast
797	/// contact bounces elastically (with restitution); a slow one below <c>RestThreshold</c>
798	/// is treated as resting — the approach is merely cancelled — so dense piles settle
799	/// instead of jittering. A floor-tagged collider adds an extra upward impulse so the
800	/// boost showcase stays in motion.
801	///
802	/// Replaces the engine's <see cref="TransformCollisionResolutionSystem{T}"/>
803	/// for this demo — that system zeros velocity along the normal (kinematic
804	/// "stop"), which would defeat the bouncing behaviour we want here.
805	public class BallBounceSystem : ISystem<GameState>
806	{
807	    private const float Restitution = 0.92f;     // energy retention per bounce (higher = less loss)
808	    private const float FloorBoost = 260f;
809	    private const float FlashImpactSpeed = 40f;  // min closing speed that counts as a wall impact
810	
811	    // Resting-contact handling so dense piles settle instead of jittering. Below
812	    // RestThreshold a contact is "resting": restitution drops to 0 (cancel only the
813	    // inward normal velocity) instead of bouncing, so gravity's ~20 px/s per-frame
814	    // nudge no longer micro-bounces a ball forever. PenetrationSlop + PositionCorrection
815	    // do Baumgarte-style positional correction — push out most of the overlap each
816	    // frame, leaving a sub-pixel slop — so balls sit visually tangent rather than sunk
817	    // into each other. The slop is also a deadband: once a settled (asleep) pile relaxes
818	    // below it, corrections stop entirely, so the pile reaches a true fixed point instead
819	    // of perpetually nudging. Damped below 1.0 so packed neighbours don't over-separate.
820	    // All of this engages only at low speed, so active bouncing (and the floor-boost
821	    // showcase) is untouched.
822	    private const float RestThreshold      = 50f;   // closing speed below which a contact is "resting"
823	    private const float PenetrationSlop    = 0.2f;  // overlap (px) left uncorrected — a deadband for stillness
824	    private const float PositionCorrection = 0.8f;  // fraction of the remaining overlap pushed out per frame
825	
826	    /// Bright pop both balls blink to when two balls collide — distinct from (and
827	    /// brighter than) the per-ball wall-hit tint, and fired regardless of speed.
828	    private static readonly Color BallCollisionFlashColor = new(255, 255, 235);
829	
830	    private readonly World _world;
831	    private readonly PhysicsDemoScreen _screen;
832	    private readonly List<CollisionMessage> _collisions = new();
833	
834	    public bool IsEnabled { get; set; } = true;
835	
836	    public BallBounceSystem(World world, PhysicsDemoScreen screen)
837	    {
838	        _world = world;
839	        _screen = screen;
840	        world.Subscribe<CollisionMessage>(OnCollision);
841	    }
842	
843	    private void OnCollision(in CollisionMessage msg) => _collisions.Add(msg);
844	
845	    public void Update(GameState state)
846	    {
847	        if (!IsEnabled)
848	        {
849	            _collisions.Clear();
850	            return;
851	        }
852	
853	        foreach (var msg in _collisions)
854	        {
855	            Resolve(msg);
856	        }
857	        _collisions.Clear();
858	    }
859	
860	    private void Resolve(CollisionMessage msg)
861	    {
862	        var entity = msg.BaseEntity;
863	        var other  = msg.CollidingEntity;
864	        if (!entity.IsAlive || !other.IsAlive) return;
865	
866	        // Walls have no velocity component (and shouldn't move); guard.
867	        if (!entity.Has<VelocityComponent>() || !entity.Has<TransformComponent>()) return;
868	
869	        // Filter blue↔blue: blue balls only collide with walls. They share a
870	        // layer (BlueBallLayer), so the detection system emits the message; we
871	        // discard it here. (Red↔blue is already filtered by layer mismatch.)
872	        if (entity.Has<BallTagComponent>() && other.Has<BallTagComponent>())
873	        {
874	            var a = entity.Get<BallTagComponent>().Type;
875	            var b = other.Get<BallTagComponent>().Type;
876	            if (a == BallType.Blue && b == BallType.Blue) return;
877	        }
878	
879	        ref var transform = ref entity.Get<TransformComponent>();
880	        ref var velocity = ref entity.Get<VelocityComponent>();
881	
882	        var normal = msg.ContactNormal;
883	        if (normal == Vector2.Zero) return;
884	        var penetration = msg.PenetrationDepth;
885	
886	        // SAT normal points from A's center toward B's center, i.e. "into the
887	        // collision" from A's perspective. Push A out along -normal.
888	        // For ball↔ball we apply half-push because the symmetric message
889	        // (A=B, B=A) will arrive too and push the other half; for ball↔wall
890	        // the wall is static and the swept self-skip ensures it never iterates
891	        // as A, so a single full push is correct here.
892	        var isBallVsBall = entity.Has<BallTagComponent>() && other.Has<BallTagComponent>();
893	        var pushScale = isBallVsBall ? 0.5f : 1f;
894	
895	        // Soft positional correction: leave a slop of overlap and push out only a
896	        // fraction of the rest this frame. Full immediate correction makes packed
897	        // neighbours fight (resolve A↔B → A penetrates C → resolve A↔C → back),
898	        // which reads as jitter; the small residual overlap is sub-pixel.
899	        var correction = MathF.Max(0f, penetration - PenetrationSlop) * PositionCorrection;
900	        if (correction > 0f)
901	            transform.Translate(-normal * correction * pushScale);
902	
903	        // Velocity response uses the RELATIVE normal velocity (closing speed), so a
904	        // ball hit while at rest still absorbs the impact instead of acting like a
905	        // wall. Equal-mass balls split the impulse — each symmetric message (A→B and
906	        // B→A) applies half, summing to the full two-body exchange — while a ball↔wall
907	        // contact (infinite mass, no symmetric message) takes the full reflection.
908	        // With other's velocity zero this reduces exactly to reflecting the ball's own
909	        // velocity, so wall bounces and head-on ball pairs are unchanged. Only act when
910	        // closing (> 0); a separating pair is already parting and must not be glued.
911	        var otherVelocity = other.Has<VelocityComponent>()
912	            ? other.Get<VelocityComponent>().Current
913	            : Vector2.Zero;
914	        var closingSpeed = Vector2.Dot(velocity.Current - otherVelocity, normal);
915	        var isResting = closingSpeed < RestThreshold;
916	        if (closingSpeed > 0f)
917	        {
918	            // Resting contact → restitution 0: just kill the approach so the ball
919	            // settles (tangential motion survives, so it can still slide/roll). A real
920	            // impact → elastic exchange with restitution.
921	            var restitution = isResting ? 0f : Restitution;
922	            var massFactor = isBallVsBall ? 0.5f : 1f;
923	            velocity.Current -= massFactor * (1f + restitution) * closingSpeed * normal;
924	
925	            // A genuine impact (above the rest threshold) wakes a settled ball so
926	            // gravity and integration resume and the impulse above isn't frozen away
927	            // next frame by BallRestSystem. Resting contacts stay below it, so a quiet
928	            // pile never wakes itself.
929	            if (!isResting)
930	            {
931	                Wake(entity);
932	                Wake(other);
933	            }
934	        }
935	
936	        var hitFloor = other.Has<FloorTag>();
937	
938	        // Floor kick: extra upward impulse on top of the elastic bounce.
939	        if (_screen.FloorBoostEnabled && hitFloor)
940	        {
941	            // Subtract because Y-down: upward is -Y.
942	            velocity.Current.Y -= FloorBoost;
943	        }
944	
945	        // Two balls colliding pop a bright flash on BOTH balls — independent of which
946	        // is this message's base entity. Gated by the rest threshold (not by which
947	        // ball is faster) so a genuine hit at any real speed flashes, but balls in a
948	        // settled pile (sustained sub-threshold contact) decay back to their resting
949	        // tint instead of glowing at the flash color forever. Wall hits keep the
950	        // per-ball tint, gated by a minimum closing speed.
951	        if (isBallVsBall)
952	        {
953	            if (!isResting)
954	            {
955	                Flash(entity, BallCollisionFlashColor);
956	                Flash(other, BallCollisionFlashColor);
957	            }
958	        }
959	        else if (closingSpeed > FlashImpactSpeed)
960	        {
961	            Flash(entity, PhysicsDemoScreen.BallColors(entity.Get<BallTagComponent>().Type).Flash);
962	            if (hitFloor && _screen.FloorBoostEnabled) Flash(_screen.FloorVisual);
963	        }
964	    }
965	
966	    /// Wakes a sleeping ball so gravity and integration resume next frame
967	    /// (<see cref="BallRestSystem"/> stops freezing it once <c>Asleep</c> clears).
968	    private static void Wake(Entity e)
969	    {
970	        if (!e.IsAlive || !e.Has<BallTagComponent>()) return;
971	        ref var tag = ref e.Get<BallTagComponent>();
972	        if (!tag.Asleep && tag.StillTime == 0f) return;
973	        tag.Asleep = false;
974	        tag.StillTime = 0f;
975	    }
976	
977	    /// (Re)trigger an entity's blink, keeping its existing <see cref="FlashComponent.FlashColor"/>.
978	    private static void Flash(Entity e)
979	    {
980	        if (!e.IsAlive || !e.Has<FlashComponent>()) return;
981	        ref var flash = ref e.Get<FlashComponent>();
982	        flash.Remaining = flash.Duration;
983	    }
984	
985	    /// (Re)trigger an entity's blink with an explicit color. <see cref="FlashSystem"/> shows
986	    /// <c>BaseColor</c> when idle, so overwriting <c>FlashColor</c> here only colors the blink
987	    /// this call starts — letting wall hits and ball↔ball hits blink different colors.
988	    private static void Flash(Entity e, Color flashColor)
989	    {
990	        if (!e.IsAlive || !e.Has<FlashComponent>()) return;
991	        ref var flash = ref e.Get<FlashComponent>();
992	        flash.FlashColor = flashColor;
993	        flash.Remaining = flash.Duration;
994	    }
995	
996	    public void Dispose()
997	    {
998	        _collisions.Clear();
999	        GC.SuppressFinalize(this);
1000	    }
1001	}
1002	
1003	// ─── flash / blink ─────────────────────────────────────────────────────────
1004	
1005	/// Drives <see cref="FlashComponent"/>: every frame it repaints a mesh entity's
1006	/// vertex colors to either its resting <c>BaseColor</c> (when idle) or a value
1007	/// lerped from <c>FlashColor</c> back toward <c>BaseColor</c> while a blink decays.
1008	/// Writes colors in place (no allocation), so it must run in the update pipeline
1009	/// before the mesh prep / render stage reads the vertices.
1010	public class FlashSystem(World world)
1011	    : AEntitySetSystem<GameState>(world.GetEntities().With<FlashComponent>().With<DrawComponent>().AsSet())
1012	{
1013	    protected override void Update(GameState state, in Entity entity)
1014	    {
1015	        ref var flash = ref entity.Get<FlashComponent>();
1016	        var draw = entity.Get<DrawComponent>();
1017	        if (draw.Vertices is not { Length: > 0 } vertices) return;
1018	
1019	        Color color;
1020	        if (flash.Remaining > 0f)
1021	        {
1022	            flash.Remaining = MathF.Max(0f, flash.Remaining - state.Time);
1023	            var t = flash.Duration > 0f ? flash.Remaining / flash.Duration : 0f;
1024	            color = Color.Lerp(flash.BaseColor, flash.FlashColor, t);
1025	        }
1026	        else
1027	        {
1028	            color = flash.BaseColor;
1029	        }
1030	
1031	        for (var i = 0; i < vertices.Length; i++)
1032	            vertices[i].Color = color;
1033	    }
1034	}
1035	
1036	// ─── speed clamp ───────────────────────────────────────────────────────────
1037	
1038	/// Caps each ball's velocity magnitude. The floor boost adds fixed energy on every
1039	/// bounce (the demo is "self-sustaining, not damped"), which otherwise compounds
1040	/// until a ball is fast enough to tunnel through a wall in a single step. Clamping
1041	/// the speed bounds the energy and keeps the balls contained. Runs after the bounce
1042	/// system (the last writer of ball velocity) so the cap is the final word.
1043	public class BallSpeedClampSystem(World world, float maxSpeed)
1044	    : AEntitySetSystem<GameState>(world.GetEntities().With<BallTagComponent>().With<VelocityComponent>().AsSet())
1045	{
1046	    protected override void Update(GameState state, in Entity entity)
1047	    {
1048	        ref var velocity = ref entity.Get<VelocityComponent>();
1049	        var speedSq = velocity.Current.LengthSquared();
1050	        if (speedSq > maxSpeed * maxSpeed)
1051	            velocity.Current = velocity.Current * (maxSpeed / MathF.Sqrt(speedSq));
1052	    }
1053	}
1054	
1055	// ─── resting / sleep ───────────────────────────────────────────────────────
1056	
1057	/// Lets a settled ball stop being integrated so dense piles go truly still. With
1058	/// gravity on, every ball is nudged ~g·dt downward each frame and moved into its
1059	/// contact *before* detection runs, so the resolver is forever correcting a sink it
1060	/// can't prevent — that residual sink↔correct cycle is the "resting jitter" (and the
1061	/// reason a small overlap lingers instead of reaching zero). This system breaks the
1062	/// cycle: once a ball's speed stays below SleepSpeed for SleepDelay it is marked
1063	/// asleep, and thereafter its velocity is zeroed here — right after gravity, before
1064	/// integration — cancelling the gravity nudge so it neither sinks nor jitters. The
1065	/// bounce system's position correction still runs, so a freshly-slept ball relaxes
1066	/// the last of its overlap to tangent and then quiesces against the slop deadband.
1067	/// Balls wake on a deep incursion (<see cref="BallBounceSystem"/>) or any demo toggle
1068	/// (<see cref="PhysicsDemoScreen.WakeAllBalls"/>). Gated on GravityEnabled so it acts
1069	/// only in the gravity-on settling case — never while paused, and never in the lively
1070	/// floor-boost showcase, where balls never slow enough to sleep anyway.
1071	public class BallRestSystem : ISystem<GameState>
1072	{
1073	    private const float SleepSpeed = 24f;   // speed (post-gravity) under which a ball accrues still-time
1074	    private const float SleepDelay = 0.4f;  // seconds of continuous stillness before sleeping
1075	
1076	    private readonly EntitySet _balls;
1077	    private readonly PhysicsDemoScreen _screen;
1078	    public bool IsEnabled { get; set; } = true;
1079	
1080	    public BallRestSystem(World world, PhysicsDemoScreen screen)
1081	    {
1082	        _screen = screen;
1083	        _balls = world.GetEntities().With<BallTagComponent>().With<VelocityComponent>().AsSet();
1084	    }
1085	
1086	    public void Update(GameState state)
1087	    {
1088	        if (!IsEnabled || !_screen.GravityEnabled) return;
1089	
1090	        foreach (var entity in _balls.GetEntities())
1091	        {
1092	            ref var tag = ref entity.Get<BallTagComponent>();
1093	            var velocity = entity.Get<VelocityComponent>();
1094	
1095	            if (tag.Asleep)
1096	            {
1097	                velocity.Current = Vector2.Zero;   // cancel the gravity just applied → frozen
1098	                continue;
1099	            }
1100	
1101	            if (velocity.Current.LengthSquared() < SleepSpeed * SleepSpeed)
1102	            {
1103	                tag.StillTime += state.Time;
1104	                if (tag.StillTime >= SleepDelay)
1105	                {
1106	                    tag.Asleep = true;
1107	                    velocity.Current = Vector2.Zero;
1108	                }
1109	            }
1110	            else
1111	            {
1112	                tag.StillTime = 0f;
1113	            }
1114	        }
1115	    }
1116	
1117	    public void Dispose()
1118	    {
1119	        _balls.Dispose();
1120	        GC.SuppressFinalize(this);
1121	    }
1122	}
1123

