216	        var topRight = new Vector2(Bounds.Right, Bounds.Top);
217	        var bottomRight = new Vector2(Bounds.Right, Bounds.Bottom);
218	        var bottomLeft = new Vector2(Bounds.Left, Bounds.Bottom);
