221	        LineMeshGenerator.AddLine(vertices, indices, topLeft, topRight, Thickness, Color, ref indexOffset);
222	        // Right edge
223	        LineMeshGenerator.AddLine(vertices, indices, topRight, bottomRight, Thickness, Color, ref indexOffset);
224	        // Bottom edge
225	        LineMeshGenerator.AddLine(vertices, indices, bottomRight, bottomLeft, Thickness, Color, ref indexOffset);
