233	/// <summary>
234	/// Generates a dashed rectangle outline. Each edge is broken into evenly spaced
235	/// dashes of <see cref="DashLength"/> separated by gaps of <see cref="GapLength"/>,
236	/// drawn with <see cref="Thickness"/> using <see cref="LineMeshGenerator"/> segments.
237	/// Dash spacing is fitted per-edge so every edge begins and ends on a dash — no
238	/// half-dash bleeds past a corner.
239	/// </summary>
240	public class DashedRectangleOutlineMeshGenerator : IMeshGenerator
241	{
242	    public Rectangle Bounds { get; set; }
243	    public float Thickness { get; set; }
244	    public Color Color { get; set; }
245	    public float DashLength { get; set; }
246	    public float GapLength { get; set; }
247	
248	    public DashedRectangleOutlineMeshGenerator(
249	        Rectangle bounds, float thickness, Color color, float dashLength = 12f, float gapLength = 8f)
250	    {
251	        Bounds = bounds;
252	        Thickness = thickness;
253	        Color = color;
254	        DashLength = dashLength;
255	        GapLength = gapLength;
256	    }
257	
258	    public MeshData Generate()
259	    {
260	        var vertices = new List<VertexPositionColor>();
261	        var indices = new List<int>();
262	        int indexOffset = 0;
263	
264	        var topLeft = new Vector2(Bounds.Left, Bounds.Top);
265	        var topRight = new Vector2(Bounds.Right, Bounds.Top);
266	        var bottomRight = new Vector2(Bounds.Right, Bounds.Bottom);
267	        var bottomLeft = new Vector2(Bounds.Left, Bounds.Bottom);
268	
269	        AddDashedEdge(vertices, indices, topLeft, topRight, ref indexOffset);
270	        AddDashedEdge(vertices, indices, topRight, bottomRight, ref indexOffset);
271	        AddDashedEdge(vertices, indices, bottomRight, bottomLeft, ref indexOffset);
272	        AddDashedEdge(vertices, indices, bottomLeft, topLeft, ref indexOffset);
273	
274	        return new MeshData(vertices.ToArray(), indices.ToArray());
275	    }
276	
277	    private void AddDashedEdge(
278	        List<VertexPositionColor> vertices, List<int> indices,
279	        Vector2 start, Vector2 end, ref int indexOffset)
280	    {
281	        float length = Vector2.Distance(start, end);
282	        if (length <= 0f) return;
283	        Vector2 dir = (end - start) / length;
284	
285	        // An edge too short for a single dash just gets one solid segment.
286	        if (length <= DashLength)
287	        {
288	            LineMeshGenerator.AddLine(vertices, indices, start, end, Thickness, Color, ref indexOffset);
289	            return;
290	        }
291	
292	        // Fit a whole number of dash+gap periods so the final dash lands exactly on
293	        // the corner. periods+1 dashes are drawn; the last starts at (length - DashLength).
294	        float period = DashLength + GapLength;
295	        int periods = Math.Max(1, (int)MathF.Round((length - DashLength) / period));
296	        float spacing = (length - DashLength) / periods;
297	
298	        for (int i = 0; i <= periods; i++)
299	        {
300	            float dashStart = i * spacing;
301	            float dashEnd = Math.Min(dashStart + DashLength, length);
302	            LineMeshGenerator.AddLine(
303	                vertices, indices, start + dir * dashStart, start + dir * dashEnd, Thickness, Color, ref indexOffset);
304	        }
305	    }
306	}
