323	    {
324	        var vertices = new VertexPositionColor[]
325	        {
326	            new(new Vector3(Bounds.Left, Bounds.Top, 0), Color),
327	            new(new Vector3(Bounds.Right, Bounds.Top, 0), Color),
328	            new(new Vector3(Bounds.Right, Bounds.Bottom, 0), Color),
329	            new(new Vector3(Bounds.Left, Bounds.Bottom, 0), Color)
330	        };
331	
332	        var indices = new int[] { 0, 1, 2, 0, 2, 3 };
