338	/// <summary>
339	/// Generates a gradient mesh along a path with configurable width and color function.
340	/// </summary>
341	public class GradientPathMeshGenerator : IMeshGenerator
342	{
343	    public Vector2[] PathPoints { get; set; }
344	    public float Width { get; set; }
345	    public Func<float, Color> ColorFunction { get; set; }
346	
347	    public GradientPathMeshGenerator(Vector2[] pathPoints, float width, Func<float, Color> colorFunction)
348	    {
349	        PathPoints = pathPoints;
350	        Width = width;
351	        ColorFunction = colorFunction;
352	    }
353	
354	    public MeshData Generate()
355	    {
356	        if (PathPoints == null || PathPoints.Length < 2)
357	            return new MeshData();
358	
359	        var vertices = new List<VertexPositionColor>();
360	        var indices = new List<int>();
361	
362	        for (int i = 0; i < PathPoints.Length; i++)
363	        {
364	            float t = (float)i / (PathPoints.Length - 1);
365	            var color = ColorFunction(t);
366	
367	            // Calculate perpendicular for width
368	            Vector2 direction;
369	            if (i == 0)
370	                direction = PathPoints[1] - PathPoints[0];
371	            else if (i == PathPoints.Length - 1)
372	                direction = PathPoints[i] - PathPoints[i - 1];
373	            else
374	                direction = PathPoints[i + 1] - PathPoints[i - 1];
375	
376	            direction.Normalize();
377	            var perpendicular = new Vector2(-direction.Y, direction.X) * (Width / 2);
378	
379	            vertices.Add(new VertexPositionColor(
380	                new Vector3(PathPoints[i] + perpendicular, 0), color));
381	            vertices.Add(new VertexPositionColor(
382	                new Vector3(PathPoints[i] - perpendicular, 0), color));
383	
384	            if (i > 0)
385	            {
386	                int baseIndex = (i - 1) * 2;
387	                indices.Add(baseIndex);
388	                indices.Add(baseIndex + 1);
389	                indices.Add(baseIndex + 2);
390	
391	                indices.Add(baseIndex + 1);
392	                indices.Add(baseIndex + 3);
393	                indices.Add(baseIndex + 2);
394	            }
395	        }
396	
397	        return new MeshData(vertices.ToArray(), indices.ToArray());
398	    }
399	}
400	
401	/// <summary>
402	/// Combines multiple mesh generators into a single mesh.
403	/// </summary>
404	public class CompositeMeshGenerator : IMeshGenerator
405	{
406	    private readonly List<IMeshGenerator> _generators = new();
407	
408	    public CompositeMeshGenerator Add(IMeshGenerator generator)
409	    {
410	        _generators.Add(generator);
411	        return this;
412	    }
413	
414	    public MeshData Generate()
415	    {
416	        var allVertices = new List<VertexPositionColor>();
417	        var allIndices = new List<int>();
418	
419	        foreach (var generator in _generators)
420	        {
421	            var mesh = generator.Generate();
422	            int indexOffset = allVertices.Count;
423	
424	            allVertices.AddRange(mesh.Vertices);
425	            foreach (var index in mesh.Indices)
426	            {
427	                allIndices.Add(index + indexOffset);
428	            }
429	        }
430	
431	        return new MeshData(allVertices.ToArray(), allIndices.ToArray());
432	    }
433	}
