112	    /// Creates an icon-only clickable button (used for back / exit chrome). The
113	    /// container hosts a child sprite for the icon and an outline entity for
114	    /// hit-testing. Outline color is transparent so no border draws — interaction
115	    /// is signaled by recoloring the icon sprite on hover instead.
116	    public static (Entity container, Entity outline, Vector2 size) CreateIconButton(
117	        World world,
