168	            HoveredColor = hoverTint,
169	            ActiveColor = hoverTint,
170	        });
171	        outline.Set<VisibleComponent>();
172	
173	        // Cross-link via a side component so a small extra system can recolor the icon.
174	        outline.Set(new IconRecolorTarget { Icon = icon });
175	
176	        return (container, outline, buttonSize);
177	    }
