10	namespace MonoDreams.UI;
11	
12	/// <summary>
13	/// Prepares DrawComponents with mesh data for button outlines.
14	/// This system is game-agnostic and generates generic vertex buffer data.
15	/// </summary>
16	[With(typeof(SimpleButtonComponent), typeof(TransformComponent))]
17	public class ButtonMeshPrepSystem(World world) : AEntitySetSystem<GameState>(world)
18	{
19	    protected override void Update(GameState state, in Entity entity)
20	    {
21	        ref readonly var outline = ref entity.Get<SimpleButtonComponent>();
22	        ref readonly var transform = ref entity.Get<TransformComponent>();
23	
24	        var vertices = new List<VertexPositionColor>();
25	        var indices = new List<int>();
26	        var indexOffset = 0;
27	
28	        // Calculate corners of the button using world position as top-left origin
29	        // (Layout system positions elements at their top-left corner)
30	        var position = transform.WorldPosition;
31	
32	        // Top-left, top-right, bottom-right, bottom-left corners
33	        var topLeft = position;
34	        var topRight = new Vector2(position.X + outline.Size.X, position.Y);
35	        var bottomRight = position + outline.Size;
36	        var bottomLeft = new Vector2(position.X, position.Y + outline.Size.Y);
37	
38	        // Optional solid fill behind the outline.
39	        if (outline.FillColor.A > 0)
40	        {
41	            var fill = outline.FillColor;
42	            vertices.Add(new VertexPositionColor(new Vector3(topLeft, 0), fill));
43	            vertices.Add(new VertexPositionColor(new Vector3(topRight, 0), fill));
44	            vertices.Add(new VertexPositionColor(new Vector3(bottomRight, 0), fill));
45	            vertices.Add(new VertexPositionColor(new Vector3(bottomLeft, 0), fill));
46	            indices.Add(indexOffset);
47	            indices.Add(indexOffset + 1);
48	            indices.Add(indexOffset + 2);
49	            indices.Add(indexOffset);
50	            indices.Add(indexOffset + 2);
51	            indices.Add(indexOffset + 3);
52	            indexOffset += 4;
53	        }
54	
55	        // Create thick lines for the four sides of the rectangle (skip if thickness is zero).
56	        if (outline.LineThickness > 0f)
57	        {
58	            AddThickLine(vertices, indices, topLeft, topRight, outline.LineThickness, outline.Color, ref indexOffset);
59	            AddThickLine(vertices, indices, topRight, bottomRight, outline.LineThickness, outline.Color, ref indexOffset);
60	            AddThickLine(vertices, indices, bottomRight, bottomLeft, outline.LineThickness, outline.Color, ref indexOffset);
61	            AddThickLine(vertices, indices, bottomLeft, topLeft, outline.LineThickness, outline.Color, ref indexOffset);
62	        }
63	
64	        // Set or update the DrawComponent.
65	        // Vertices above are baked in world coordinates, so WorldMatrix must be
66	        // identity (or null). When the screen also runs MeshPrepSystem (which would
67	        // otherwise write transform.WorldMatrix here) place this system AFTER
68	        // MeshPrepSystem in the draw pipeline so this assignment wins.
69	        if (!entity.Has<DrawComponent>())
70	        {
71	            entity.Set(new DrawComponent
72	            {
73	                Type = DrawElementType.Mesh,
74	                Vertices = vertices.ToArray(),
75	                Indices = indices.ToArray(),
76	                PrimitiveType = PrimitiveType.TriangleList,
77	                Target = outline.Target,
78	                LayerDepth = 0.95f,
79	                WorldMatrix = Matrix.Identity,
80	            });
81	        }
82	        else
83	        {
84	            ref var drawComponent = ref entity.Get<DrawComponent>();
85	            drawComponent.Type = DrawElementType.Mesh;
86	            drawComponent.Vertices = vertices.ToArray();
87	            drawComponent.Indices = indices.ToArray();
88	            drawComponent.PrimitiveType = PrimitiveType.TriangleList;
89	            drawComponent.Target = outline.Target;
90	            drawComponent.WorldMatrix = Matrix.Identity;
91	        }
92	    }
93	
94	    private void AddThickLine(List<VertexPositionColor> vertices, List<int> indices,
95	        Vector2 start, Vector2 end, float thickness, Color color, ref int indexOffset)
96	    {
97	        // Calculate direction and perpendicular vector for thickness
98	        Vector2 direction = end - start;
99	        Vector2 perpendicular = new Vector2(-direction.Y, direction.X);
100	        perpendicular.Normalize();
101	        perpendicular *= thickness / 2;
102	
103	        // Create the four corners of the line segment
104	        vertices.Add(new VertexPositionColor(new Vector3(start + perpendicular, 0), color));
105	        vertices.Add(new VertexPositionColor(new Vector3(start - perpendicular, 0), color));
106	        vertices.Add(new VertexPositionColor(new Vector3(end - perpendicular, 0), color));
107	        vertices.Add(new VertexPositionColor(new Vector3(end + perpendicular, 0), color));
108	
109	        // Create two triangles to form the line
110	        indices.Add(indexOffset);
111	        indices.Add(indexOffset + 1);
112	        indices.Add(indexOffset + 2);
113	
114	        indices.Add(indexOffset);
115	        indices.Add(indexOffset + 2);
116	        indices.Add(indexOffset + 3);
117	
118	        indexOffset += 4;
119	    }
120	}
