1	using System.Collections.Generic;
2	using System.Linq;
3	using DefaultEcs;
4	using DefaultEcs.System;
5	using Microsoft.Xna.Framework;
6	using Microsoft.Xna.Framework.Graphics;
7	using MonoDreams.Component;
8	using MonoDreams.Component.Draw;
9	using MonoDreams.State;
10	using MonoGame.Extended.BitmapFonts;
11	
12	namespace MonoDreams.System.Draw;
13	
14	/// <summary>
15	/// Unified rendering system that handles all draw types: sprites, text, nine-patch, and mesh.
16	/// This system is game-agnostic — it only renders what's in DrawComponent without any
17	/// specialized component handling.
18	/// <para>
19	/// One instance renders a single pass: every entity whose <see cref="DrawComponent.Target"/>
20	/// equals <paramref name="source"/>, through the optional <paramref name="camera"/> view
21	/// transform (null ⇒ screen-space, no transform), into <paramref name="destination"/>.
22	/// Compose multiple instances for multiple views — e.g. the world (Main) through the main
23	/// camera, plus UI and HUD screen-space passes, plus a minimap (Main through a second camera
24	/// into its own target), splitscreen, CCTV, or portal textures. The instances are independent
25	/// render passes; <see cref="FinalDrawSystem"/> arranges their targets onto the screen.
26	/// </para>
27	/// </summary>
28	public class MasterRenderSystem(
29	    SpriteBatch spriteBatch,
30	    GraphicsDevice graphicsDevice,
31	    World world,
32	    RenderTargetID source,
33	    RenderTarget2D destination,
34	    MonoDreams.Component.Camera? camera = null,
35	    SamplerState? spriteSampler = null,
36	    SamplerState? textSampler = null) : ISystem<GameState>
37	{
38	    private BasicEffect? _basicEffect;
39	
40	    // The draw set for this pass, built once and reused for the system's lifetime.
41	    // AsSet() registers subscriptions the World keeps alive forever — building a fresh
42	    // set every frame leaks an EntitySet + its subscriptions per frame, so memory climbs
43	    // even on a static scene. See premise "Per-target draw sets are built once, not per frame".
44	    private EntitySet? _drawSet;
45	
46	    private EntitySet DrawSet => _drawSet ??= BuildDrawSet();
47	
48	    private EntitySet BuildDrawSet()
49	    {
50	        var queryBuilder = world.GetEntities()
51	            .With((in DrawComponent e) => e.Target == source);
52	
53	        // The world (Main) respects CullingSystem visibility; screen-space passes always render.
54	        if (source == RenderTargetID.Main)
55	            queryBuilder = queryBuilder.With<VisibleComponent>();
56	
57	        return queryBuilder.AsSet();
58	    }
59	
60	    // Pixel art wants nearest-neighbour for sprites (and meshes); downscaled bitmap fonts
61	    // read better with linear filtering — so each draw type gets its own sampler. Both are
62	    // overridable per game; the defaults suit this engine's pixel-art content.
63	    private SamplerState SpriteSamplerState => spriteSampler ?? SamplerState.PointClamp;
64	    private SamplerState TextSamplerState => textSampler ?? SamplerState.LinearClamp;
65	
66	    private enum BatchType { None, Sprite, Text, Mesh }
67	
68	    private static BatchType GetBatchType(DrawElementType type) => type switch
69	    {
70	        DrawElementType.Mesh => BatchType.Mesh,
71	        DrawElementType.Text => BatchType.Text,
72	        _ => BatchType.Sprite,
73	    };
74	
75	    // The mesh ortho projection maps this destination's pixel space to NDC. Derived from the
76	    // destination size (not the camera) so screen-space passes need no camera; the camera's
77	    // virtual resolution must match the destination size (it centers the view there).
78	    private Matrix Projection() =>
79	        Matrix.CreateOrthographicOffCenter(0, destination.Width, destination.Height, 0, 0, 1);
80	
81	    private void EnsureBasicEffect()
82	    {
83	        _basicEffect ??= new BasicEffect(graphicsDevice)
84	        {
85	            VertexColorEnabled = true,
86	            View = Matrix.Identity,
87	            Projection = Projection(),
88	        };
89	    }
90	
91	    private void BeginSpriteBatch(Matrix transformMatrix, SamplerState samplerState)
92	    {
93	        spriteBatch.Begin(
94	            sortMode: SpriteSortMode.Deferred, // We pre-sort, so no need for FrontToBack
95	            blendState: BlendState.AlphaBlend,
96	            samplerState: samplerState,
97	            depthStencilState: DepthStencilState.None,
98	            rasterizerState: RasterizerState.CullNone,
99	            effect: null,
100	            transformMatrix: transformMatrix);
101	    }
102	
103	    private void EndSpriteBatch() => spriteBatch.End();
104	
105	    private void ResetGraphicsStateForMeshRendering()
106	    {
107	        // Reset states after SpriteBatch.End() before mesh rendering
108	        graphicsDevice.BlendState = BlendState.AlphaBlend;
109	        graphicsDevice.DepthStencilState = DepthStencilState.None;
110	        graphicsDevice.RasterizerState = RasterizerState.CullNone;
111	        graphicsDevice.SamplerStates[0] = SamplerState.PointClamp;
112	    }
113	
114	    public void Update(GameState state)
115	    {
116	        EnsureBasicEffect();
117	
118	        graphicsDevice.SetRenderTarget(destination);
119	        graphicsDevice.Clear(Color.Transparent);
120	
121	        var transformMatrix = camera?.GetViewTransformationMatrix() ?? Matrix.Identity;
122	
123	        // Sort ALL entities by LayerDepth (stable sort preserves order for same depth)
124	        var entities = DrawSet.GetEntities().ToArray();
125	        var sortedEntities = entities
126	            .Select((entity, index) => (entity, index, dc: entity.Get<DrawComponent>()))
127	            .Where(x => x.dc.Type != DrawElementType.Mesh || x.dc.HasValidMesh)
128	            .OrderBy(x => x.dc.LayerDepth)
129	            .ThenBy(x => x.index) // Stable sort
130	            .ToList();
131	
132	        if (sortedEntities.Count > 0)
133	            RenderInterleaved(sortedEntities, transformMatrix);
134	    }
135	
136	    private void RenderInterleaved(
137	        List<(Entity entity, int index, DrawComponent dc)> sortedEntities,
138	        Matrix transformMatrix)
139	    {
140	        BatchType currentBatch = BatchType.None;
141	
142	        foreach (var (_, _, dc) in sortedEntities)
143	        {
144	            var requiredBatch = GetBatchType(dc.Type);
145	
146	            // Batch type changed - switch context. Sprite and Text both use the SpriteBatch
147	            // but with different samplers, so switching between them flushes + reopens it.
148	            // Painter's order is preserved because the list is already depth-sorted.
149	            if (requiredBatch != currentBatch)
150	            {
151	                // End previous batch
152	                if (currentBatch is BatchType.Sprite or BatchType.Text)
153	                    EndSpriteBatch();
154	
155	                // Start new batch
156	                if (requiredBatch == BatchType.Sprite)
157	                    BeginSpriteBatch(transformMatrix, SpriteSamplerState);
158	                else if (requiredBatch == BatchType.Text)
159	                    BeginSpriteBatch(transformMatrix, TextSamplerState);
160	                else if (requiredBatch == BatchType.Mesh)
161	                    ResetGraphicsStateForMeshRendering();
162	
163	                currentBatch = requiredBatch;
164	            }
165	
166	            // Draw the element
167	            if (requiredBatch == BatchType.Mesh)
168	                DrawSingleMesh(dc, transformMatrix);
169	            else
170	                DrawElement(dc); // Sprite or Text
171	        }
172	
173	        // End final batch if it was a SpriteBatch one
174	        if (currentBatch is BatchType.Sprite or BatchType.Text)
175	            EndSpriteBatch();
176	    }
177	
178	    private void DrawSingleMesh(DrawComponent dc, Matrix transformMatrix)
179	    {
180	        if (!dc.HasValidMesh) return;
181	
182	        _basicEffect!.Projection = Projection();
183	        _basicEffect.World = (dc.WorldMatrix ?? Matrix.Identity) * transformMatrix;
184	
185	        foreach (var pass in _basicEffect.CurrentTechnique.Passes)
186	        {
187	            pass.Apply();
188	            graphicsDevice.DrawUserIndexedPrimitives(
189	                dc.PrimitiveType,
190	                dc.Vertices,
191	                0,
192	                dc.Vertices!.Length,
193	                dc.Indices,
194	                0,
195	                dc.GetPrimitiveCount());
196	        }
197	    }
198	
199	    private void DrawElement(DrawComponent element)
200	    {
201	        switch (element.Type)
202	        {
203	            case DrawElementType.Sprite:
204	                if (element.Texture == null) return;
205	
206	                // Calculate scale from source to destination size for sub-pixel precision
207	                Vector2 scale;
208	                if (element.SourceRectangle.HasValue && element.SourceRectangle.Value.Width > 0 && element.SourceRectangle.Value.Height > 0)
209	                {
210	                    scale = new Vector2(
211	                        element.Size.X / element.SourceRectangle.Value.Width,
212	                        element.Size.Y / element.SourceRectangle.Value.Height);
213	                }
214	                else
215	                {
216	                    scale = element.Scale;
217	                }
218	
219	                spriteBatch.Draw(
220	                    element.Texture,
221	                    element.Position,  // Vector2 preserves sub-pixel precision
222	                    element.SourceRectangle,
223	                    element.Color,
224	                    element.Rotation,
225	                    element.Origin,
226	                    scale,
227	                    SpriteEffects.None,
228	                    element.LayerDepth);
229	                break;
230	
231	            case DrawElementType.Text:
232	                if (element.Font == null || element.Text == null) return;
233	
234	                // Lay out multi-line text ourselves: one DrawString per '\n'-separated line,
235	                // advancing by the (scaled) font line height × LineSpacing. This gives a
236	                // configurable, scale-correct leading instead of relying on the font backend's
237	                // internal newline advance (which ignores the draw scale and overlaps lines).
238	                var lineSpacing = element.LineSpacing > 0 ? element.LineSpacing : DynamicTextComponent.DefaultLineSpacing;
239	                var lineAdvance = element.Font.LineHeight * element.Scale.Y * lineSpacing;
240	                var lines = element.Text.Split('\n');
241	                for (var i = 0; i < lines.Length; i++)
242	                {
243	                    spriteBatch.DrawString(
244	                        element.Font,
245	                        lines[i],
246	                        element.Position + new Vector2(0f, i * lineAdvance),
247	                        element.Color,
248	                        element.Rotation,
249	                        element.Origin,
250	                        element.Scale,
251	                        SpriteEffects.None,
252	                        element.LayerDepth);
253	                }
254	                break;
255	
256	            case DrawElementType.NinePatch:
257	                // NinePatch handled by SpritePrepSystem creating 9 sprite elements
258	                break;
259	
260	            case DrawElementType.Mesh:
261	                // Handled separately in DrawSingleMesh via RenderInterleaved
262	                break;
263	        }
264	    }
265	
266	    public void Dispose()
267	    {
268	        _basicEffect?.Dispose();
