    {
        _scale.Y = y;
        SetDirty();
        return this;
    }

    /// <summary>Sets uniform scale.</summary>
    public TransformComponent SetScale(float uniform)
    {
        _scale = new Vector2(uniform, uniform);
        SetDirty();
        return this;
    }

    /// <summary>Multiplies scale by a factor.</summary>
    public TransformComponent ScaleBy(Vector2 factor)
    {
        _scale *= factor;
        SetDirty();
        return this;
    }

    /// <summary>Multiplies scale uniformly by a factor.</summary>
    public TransformComponent ScaleBy(float factor)
    {
        _scale *= factor;
        SetDirty();
        return this;
    }

    #endregion

    #region Fluent Origin Methods

    /// <summary>Sets the X component of origin.</summary>
    public TransformComponent SetOriginX(float x)
    {
        _origin.X = x;
        SetDirty();
        return this;
    }

    /// <summary>Sets the Y component of origin.</summary>
    public TransformComponent SetOriginY(float y)
    {
        _origin.Y = y;
        SetDirty();
        return this;
    }

    #endregion
}

